import pandas as pd
import os

files = {
    'exp1': experiment_1_csv,
    'exp2': experiment_2_csv,
    'exp4': experiment_4_csv
}

for name, path in files.items():
    if os.path.exists(path):
        df = pd.read_csv(path)
        print(f"\n=== {name.upper()} ===")
        print("Columns:", df.columns.tolist())
        print(df.describe().round(2))
        if 'WaterClarityScore' in df.columns:
            print("\nCorrelation with Clarity:")
            print(df.corr(numeric_only=True)['WaterClarityScore'].round(3))
    else:
        print(f"{path} not found")
